    AddSpawnedFunction(new CSpawnedFunc<CQ_WhiteBalverineWWScript>("SpawnBalverines", 0, this, &CQ_WhiteBalverineWWScript::SpawnBalverines), CCharString(""));
    {
        CScriptGameResourceObjectScriptedThingBase seh_balverine;
